/**
 * Create a topology-backed status effect node under `actorId`.
 *
 * @param {import("../../lib/ecs-js/index.js").World} world
 * @param {number} actorId
 * @param {{
 *   key:string,
 *   turnsLeft:number,
 *   maxTurns?:number,
 *   startedAtTurn?:number,
 *   potency?:number,
 *   stacks?:number,
 *   sourceId?:number,
 *   sourceKind?:string,
 *   sourceKey?:string,
 *   onsetLeft?:number,
 * }} effect
